const path=require('node:path');
const {KdrgSearchService}=require('./src/kdrg-search-service');
const Ui=require('./renderer/ui-formatters');

const service=new KdrgSearchService(
  path.resolve('..','data','kdrg_v47_search_integrated_v3.json')
);

const d=service.getDetail('AADRG','P6510').detail;
if(d.adrg!=='P651') throw new Error('P6510 parent mismatch');
if(!d.condition_ast) throw new Error('P6510 inherited condition_ast missing');

const tree=Ui.buildPrettyConditionTree(d.condition_ast);
if(!tree) throw new Error('P651 pretty tree missing');

function count(n){
  if(!n) return 0;
  if(n.kind==='group') {
    return 1+(n.children||[]).reduce((a,c)=>a+count(c),0);
  }
  if(n.kind==='not') return 1+count(n.child);
  if(n.kind==='without') return 1+count(n.left)+count(n.right);
  return 1;
}

if(count(tree)<3) {
  throw new Error('P651 pretty tree unexpectedly shallow');
}

console.log(
  '[PASS] P6510 inherited AST -> pretty tree',
  JSON.stringify({kind:tree.kind,nodes:count(tree)})
);
